import { normalizeDeducoesOutput, normalizeIrOutput, uid } from '@/functions/calculator-triggers/schema';
import type { TriggerScenario } from '@/types/calculator-triggers';

export function normalizeScenarioFromServer(scenario: TriggerScenario): TriggerScenario {
    return {
        ...scenario,
        outputs: (scenario.outputs ?? []).map((output) =>
            output.field === 'outrasDeducoes'
                ? { ...output, value: normalizeDeducoesOutput(output.value) }
                : output.field === 'incideIR'
                  ? { ...output, value: normalizeIrOutput(output.value) }
                  : output,
        ),
    };
}

export function normalizeScenariosFromServer(scenarios: TriggerScenario[]): TriggerScenario[] {
    return (scenarios ?? []).map(normalizeScenarioFromServer);
}

function scenarioSnapshotForCompare(scenario: TriggerScenario): string {
    return JSON.stringify({ ...scenario, audit: undefined });
}

export function isScenarioDirty(local: TriggerScenario, saved: TriggerScenario | undefined): boolean {
    if (!saved) return true;
    return scenarioSnapshotForCompare(local) !== scenarioSnapshotForCompare(saved);
}

/** Full local list order; only the target scenario is taken from local edits. */
export function buildMergedScenariosForSave(
    localScenarios: TriggerScenario[],
    savedScenarios: TriggerScenario[],
    targetScenarioId: string,
): TriggerScenario[] {
    const savedById = new Map(savedScenarios.map((scenario) => [scenario.id, scenario]));

    return localScenarios.map((local) => {
        if (local.id === targetScenarioId) return local;
        return savedById.get(local.id) ?? local;
    });
}

export function wasScenarioPersisted(scenarioId: string, savedScenarios: TriggerScenario[]): boolean {
    return savedScenarios.some((scenario) => scenario.id === scenarioId);
}

/** Clones a scenario with fresh ids; audit is cleared (new scenario). */
export function duplicateScenario(scenario: TriggerScenario, index: number): TriggerScenario {
    const baseName = scenario.name?.trim() || `Cenário ${index + 1}`;

    return {
        ...scenario,
        id: uid(),
        name: `${baseName} (cópia)`,
        audit: undefined,
        conditions: (scenario.conditions ?? []).map((condition) => ({
            ...condition,
            id: uid(),
        })),
        outputs: (scenario.outputs ?? []).map((output) => ({
            ...output,
            id: uid(),
        })),
    };
}

