import { describe, expect, it } from '@jest/globals';

import {
    detectOutputConflicts,
    evaluateAll,
} from '@/functions/calculator-triggers/engine';
import { detectPotentialOutputConflicts } from '@/functions/calculator-triggers/potential-conflicts';
import {
    aliquotaToFormPercent,
    buildFormPatchFromApplied,
    buildTriggerPatch,
    enforceTributariaIrConstraints,
    formValuesToOficio,
    triggerPercentToFormDecimal,
    triggerPercentToFormDisplay,
} from '@/functions/calculator-triggers/mappers';
import {
    findDuplicateScenarioGroups,
    normalizeIrOutput,
    normalizeScenarioIrForTributaria,
    scenarioConditionsFingerprint,
    scenarioFingerprint,
    scenarioHasTributariaNaturezaCondition,
    validateConfig,
    validateScenario,
} from '@/functions/calculator-triggers/schema';
import {
    PERSON_TYPE_PF,
    PERSON_TYPE_PJ,
    resolvePersonTypeFromDocument,
} from '@/functions/calculator-triggers/person-type';
import { canManageCalculatorTriggers } from '@/services/calculator-triggers';
import type { TriggerScenario } from '@/types/calculator-triggers';

describe('resolvePersonTypeFromDocument', () => {
    it('identifica PF e PJ pelo documento', () => {
        expect(resolvePersonTypeFromDocument('123.456.789-09')).toBe(PERSON_TYPE_PF);
        expect(resolvePersonTypeFromDocument('12.345.678/9012-34')).toBe(PERSON_TYPE_PJ);
    });

    it('mapeia cpf_cnpj do form para tipo de pessoa no ofício', () => {
        const oficio = formValuesToOficio({ cpf_cnpj: '123.456.789-09' });
        expect(oficio.cpfCnpj).toBe(PERSON_TYPE_PF);
    });
});

describe('calculator-triggers engine', () => {
    const scenario: TriggerScenario = {
        id: 's1',
        name: 'Federal',
        logic: 'AND',
        conditions: [{ id: 'c1', field: 'esfera', operator: 'eq', value: 'Federal' }],
        outputs: [
            {
                id: 'o1',
                field: 'incideIR',
                value: {
                    ativo: true,
                    modo: 'tipoValor',
                    tipoValor: 'Porcentagem',
                    aliquota: '3%',
                    baseCalculo: 'Principal',
                    deducContrib: 'Não',
                    deducHonor: 'Sim',
                    numeroMeses: '',
                },
            },
        ],
    };

    it('avalia tribunal quando valor está em lista multiselect', () => {
        const tribunalScenario: TriggerScenario = {
            id: 's-trib',
            name: 'TJs Nordeste',
            logic: 'AND',
            conditions: [
                {
                    id: 'c1',
                    field: 'tribunal',
                    operator: 'eq',
                    value: ['TJPE', 'TJSP', 'TJCE'],
                },
            ],
            outputs: [
                {
                    id: 'o1',
                    field: 'incideIR',
                    value: {
                        ativo: true,
                        modo: 'tipoValor',
                        tipoValor: 'Porcentagem',
                        aliquota: '3%',
                        baseCalculo: 'Principal',
                        deducContrib: 'Não',
                        deducHonor: 'Sim',
                        numeroMeses: '',
                    },
                },
            ],
        };

        const matchPe = evaluateAll([tribunalScenario], formValuesToOficio({ tribunal: 'TJPE' }));
        const matchMg = evaluateAll([tribunalScenario], formValuesToOficio({ tribunal: 'TJMG' }));

        expect(matchPe).toHaveLength(1);
        expect(matchMg).toHaveLength(0);
    });

    it('avalia cenário compatível com valores do formulário', () => {
        const oficio = formValuesToOficio({ esfera: 'FEDERAL' });
        const applied = evaluateAll([scenario], oficio);
        expect(applied).toHaveLength(1);
        const patch = buildFormPatchFromApplied(applied);
        expect(patch.incidencia_ir).toBe(true);
        expect(patch.imposto_de_renda_percentual).toBe('0.0300');
    });

    it('mapeia classe_credito do formulário para condição classeCredito', () => {
        const classeScenario: TriggerScenario = {
            id: 'classe-1',
            name: 'Alimentar Remuneratória',
            logic: 'AND',
            conditions: [
                {
                    id: 'c1',
                    field: 'classeCredito',
                    operator: 'eq',
                    value: 'Alimentar (Remuneratória)',
                },
            ],
            outputs: [
                {
                    id: 'o1',
                    field: 'outrasDeducoes',
                    value: { ativo: false, deducoes: [] },
                },
            ],
        };

        const match = evaluateAll(
            [classeScenario],
            formValuesToOficio({ classe_credito: 'Alimentar (Remuneratória)' }),
        );
        const miss = evaluateAll(
            [classeScenario],
            formValuesToOficio({ classe_credito: 'Desapropriação' }),
        );

        expect(formValuesToOficio({ classe_credito: 'Alimentar (Remuneratória)' }).classeCredito).toBe(
            'Alimentar (Remuneratória)',
        );
        expect(match).toHaveLength(1);
        expect(miss).toHaveLength(0);
    });

    it('aplica 1,5% quando IR ativo sem modo explícito', () => {
        const tributariaIr: TriggerScenario = {
            id: 's2',
            name: 'Tributária IR 1,5%',
            logic: 'AND',
            conditions: [{ id: 'c1', field: 'natureza', operator: 'eq', value: 'Tributária' }],
            outputs: [
                {
                    id: 'o1',
                    field: 'incideIR',
                    value: {
                        ativo: true,
                        aliquota: '1,5%',
                    },
                },
            ],
        };
        const oficio = formValuesToOficio({ natureza: 'TRIBUTÁRIA' });
        const applied = evaluateAll([tributariaIr], oficio);
        const patch = buildFormPatchFromApplied(applied);
        expect(patch.incidencia_ir).toBe(true);
        expect(patch.imposto_de_renda_percentual).toBe('0.0150');
    });

    it('detecta conflito entre outputs do mesmo campo', () => {
        const conflicts = detectOutputConflicts([
            {
                scenarioId: 'a',
                name: 'A',
                outputs: [
                    {
                        id: '1',
                        field: 'incideIR',
                        value: {
                            ativo: true,
                            modo: 'tipoValor',
                            tipoValor: 'Porcentagem',
                            aliquota: '3%',
                            baseCalculo: 'Principal',
                            deducContrib: 'Não',
                            deducHonor: 'Sim',
                            numeroMeses: '',
                        },
                    },
                ],
            },
            {
                scenarioId: 'b',
                name: 'B',
                outputs: [
                    {
                        id: '2',
                        field: 'incideIR',
                        value: {
                            ativo: true,
                            modo: 'tipoValor',
                            tipoValor: 'Porcentagem',
                            aliquota: '1,5%',
                            baseCalculo: 'Principal',
                            deducContrib: 'Não',
                            deducHonor: 'Sim',
                            numeroMeses: '',
                        },
                    },
                ],
            },
        ]);
        expect(conflicts).toHaveLength(1);
    });
});

describe('aliquotaToFormPercent', () => {
    it('mapeia labels do gatilho para valores do select da calculadora', () => {
        expect(aliquotaToFormPercent('1,5%')).toBe('0.0150');
        expect(aliquotaToFormPercent('3%')).toBe('0.0300');
    });

    it('defaulta 3% quando alíquota não foi identificada', () => {
        expect(aliquotaToFormPercent('')).toBe('0.0300');
        expect(aliquotaToFormPercent('   ')).toBe('0.0300');
    });
});

describe('triggerPercentToFormDecimal', () => {
    it('converte percentual BR do gatilho para decimal da calculadora', () => {
        expect(triggerPercentToFormDecimal('7,4')).toBeCloseTo(0.074);
        expect(triggerPercentToFormDecimal('3,6')).toBeCloseTo(0.036);
        expect(triggerPercentToFormDecimal(0.074)).toBeCloseTo(0.074);
    });
});

describe('triggerPercentToFormDisplay', () => {
    it('converte percentual do gatilho para exibição no Cleave', () => {
        expect(triggerPercentToFormDisplay('7,4')).toBe('7,4');
        expect(triggerPercentToFormDisplay(0.074)).toBe('7,40');
        expect(triggerPercentToFormDisplay('3,6')).toBe('3,6');
        expect(triggerPercentToFormDisplay(0.036)).toBe('3,60');
    });
});

describe('buildFormPatchFromApplied contribuição', () => {
    it('normaliza percentual de contribuição do gatilho para exibição no form', () => {
        const applied = evaluateAll(
            [
                {
                    id: 's1',
                    name: 'Contrib',
                    logic: 'AND',
                    conditions: [{ id: 'c1', field: 'esfera', operator: 'eq', value: 'Estadual' }],
                    outputs: [
                        {
                            id: 'o1',
                            field: 'contribuicaoPrevidenciaria',
                            value: {
                                ativo: true,
                                tipoValor: 'PERCENTUAL',
                                valor: '7,4',
                                baseCalculo: 'Principal selicado',
                            },
                        },
                    ],
                },
            ],
            { esfera: 'Estadual' },
        );
        const patch = buildFormPatchFromApplied(applied);
        expect(patch.percentual_de_contribuicao_previdenciaria).toBe('7,4');
        expect(patch.incide_contribuicao_previdenciaria).toBe(true);
    });
});

describe('buildTriggerPatch', () => {
    it('prioriza 1,5% do gatilho sobre default tributário de 3%', () => {
        const applied = evaluateAll(
            [
                {
                    id: 's1',
                    name: 'Tributária',
                    logic: 'AND',
                    conditions: [{ id: 'c1', field: 'natureza', operator: 'eq', value: 'Tributária' }],
                    outputs: [
                        {
                            id: 'o1',
                            field: 'incideIR',
                            value: { ativo: true, aliquota: '1,5%' },
                        },
                    ],
                },
            ],
            formValuesToOficio({ natureza: 'TRIBUTÁRIA' }),
        );
        const patch = buildTriggerPatch(applied, 'TRIBUTÁRIA');
        expect(patch.imposto_de_renda_percentual).toBe('0.0150');
    });

    it('usa 3% como fallback tributário sem gatilho de alíquota', () => {
        const patch = buildTriggerPatch([], 'TRIBUTÁRIA');
        expect(patch.imposto_de_renda_percentual).toBe('0.0300');
    });
});

describe('tributária and RRA', () => {
    it('detecta condição de natureza tributária no cenário', () => {
        expect(
            scenarioHasTributariaNaturezaCondition({
                id: 's1',
                name: 'Trib',
                logic: 'AND',
                conditions: [{ id: 'c1', field: 'natureza', operator: 'eq', value: 'Tributária' }],
                outputs: [],
            }),
        ).toBe(true);
    });

    it('rejeita output IR em modo RRA quando cenário é tributário', () => {
        const errors = validateScenario({
            id: 's1',
            name: 'Trib RRA',
            logic: 'AND',
            conditions: [{ id: 'c1', field: 'natureza', operator: 'eq', value: 'Tributária' }],
            outputs: [
                {
                    id: 'o1',
                    field: 'incideIR',
                    value: {
                        ativo: true,
                        modo: 'rra',
                        definirNumeroMeses: true,
                        numeroMeses: '12',
                        baseCalculo: 'Principal',
                    },
                },
            ],
        });
        expect(errors.some((err) => err.includes('RRA'))).toBe(true);
    });

    it('permite RRA sem definir número de meses no gatilho', () => {
        const errors = validateScenario({
            id: 's1',
            name: 'RRA aberto',
            logic: 'AND',
            conditions: [{ id: 'c1', field: 'esfera', operator: 'eq', value: 'Federal' }],
            outputs: [
                {
                    id: 'o1',
                    field: 'incideIR',
                    value: {
                        ativo: true,
                        modo: 'rra',
                        definirNumeroMeses: false,
                        baseCalculo: 'Principal selicado',
                    },
                },
            ],
        });
        expect(errors.some((err) => err.includes('meses'))).toBe(false);
    });

    it('não inclui numero_de_meses no patch quando RRA não define meses', () => {
        const applied = evaluateAll(
            [
                {
                    id: 's1',
                    name: 'RRA',
                    logic: 'AND',
                    conditions: [{ id: 'c1', field: 'esfera', operator: 'eq', value: 'Federal' }],
                    outputs: [
                        {
                            id: 'o1',
                            field: 'incideIR',
                            value: {
                                ativo: true,
                                modo: 'rra',
                                definirNumeroMeses: false,
                                baseCalculo: 'Principal',
                                deducContrib: 'Sim',
                                deducHonor: 'Sim',
                            },
                        },
                    ],
                },
            ],
            { esfera: 'Federal' },
        );
        const patch = buildFormPatchFromApplied(applied);
        expect(patch.incidencia_rra).toBe(true);
        expect(patch).not.toHaveProperty('numero_de_meses');
    });

    it('inclui numero_de_meses no patch quando RRA define meses (honorários)', () => {
        const applied = evaluateAll(
            [
                {
                    id: 's1',
                    name: 'RRA honorários',
                    logic: 'AND',
                    conditions: [{ id: 'c1', field: 'esfera', operator: 'eq', value: 'Federal' }],
                    outputs: [
                        {
                            id: 'o1',
                            field: 'incideIR',
                            value: {
                                ativo: true,
                                modo: 'rra',
                                definirNumeroMeses: true,
                                numeroMeses: '1',
                                baseCalculo: 'Principal',
                                deducContrib: 'Sim',
                                deducHonor: 'Sim',
                            },
                        },
                    ],
                },
            ],
            { esfera: 'Federal' },
        );
        const patch = buildFormPatchFromApplied(applied);
        expect(patch.numero_de_meses).toBe(1);
    });

    it('normaliza cenário tributário removendo modo RRA do output', () => {
        const normalized = normalizeScenarioIrForTributaria({
            id: 's1',
            name: 'Trib',
            logic: 'AND',
            conditions: [{ id: 'c1', field: 'natureza', operator: 'eq', value: 'Tributária' }],
            outputs: [
                {
                    id: 'o1',
                    field: 'incideIR',
                    value: { ativo: true, modo: 'rra', aliquota: '3%', numeroMeses: '12' },
                },
            ],
        });
        expect((normalized.outputs[0].value as { modo?: string }).modo).toBe('tipoValor');
    });

    it('remove RRA do patch quando natureza do formulário é tributária', () => {
        const patch = enforceTributariaIrConstraints(
            {
                incidencia_ir: true,
                incidencia_rra: true,
                numero_de_meses: 12,
                imposto_de_renda_percentual: '0.0150',
            },
            'TRIBUTÁRIA',
        );
        expect(patch.incidencia_rra).toBe(false);
        expect(patch.numero_de_meses).toBe(0);
        expect(patch.imposto_de_renda_percentual).toBe('0.0150');
    });
});

describe('normalizeIrOutput', () => {
    it('defaults modo to tipoValor when IR is active', () => {
        const normalized = normalizeIrOutput({ ativo: true, aliquota: '3%' });
        expect(normalized.modo).toBe('tipoValor');
    });

    it('passes validation for active IR without explicit modo', () => {
        const errors = validateScenario({
            id: 's1',
            name: 'IR',
            logic: 'AND',
            conditions: [{ id: 'c1', field: 'esfera', operator: 'eq', value: 'Federal' }],
            outputs: [
                {
                    id: 'o1',
                    field: 'incideIR',
                    value: { ativo: true, aliquota: '3%' },
                },
            ],
        });
        expect(errors.some((err) => err.includes('Tipo do valor'))).toBe(false);
    });
});

describe('duplicate scenarios', () => {
    const tributariaIrScenario = (id: string, name: string): TriggerScenario => ({
        id,
        name,
        logic: 'AND',
        conditions: [{ id: 'c1', field: 'natureza', operator: 'eq', value: 'Tributária' }],
        outputs: [
            {
                id: 'o1',
                field: 'incideIR',
                value: { ativo: true, aliquota: '1,5%' },
            },
        ],
    });

    it('detecta cenários com mesmas condições mesmo com outputs diferentes', () => {
        const scenarios = [
            tributariaIrScenario('s1', 'Cenário 1'),
            {
                ...tributariaIrScenario('s2', 'Cenário 2'),
                outputs: [
                    {
                        id: 'o1',
                        field: 'incideIR',
                        value: { ativo: false, aliquota: '1,5%' },
                    },
                ],
            },
        ];
        expect(scenarioConditionsFingerprint(scenarios[0])).toBe(
            scenarioConditionsFingerprint(scenarios[1]),
        );
        expect(scenarioFingerprint(scenarios[0])).not.toBe(scenarioFingerprint(scenarios[1]));
        expect(findDuplicateScenarioGroups(scenarios)).toEqual([['Cenário 1', 'Cenário 2']]);
    });

    it('bloqueia save quando há condições duplicadas na config', () => {
        const errors = validateConfig({
            version: 1,
            scenarios: [
                tributariaIrScenario('s1', 'Tributário 2000'),
                tributariaIrScenario('s2', 'Tributário 2001'),
            ],
        });
        expect(errors.some((err) => err.includes('Condições duplicadas'))).toBe(true);
    });

    it('bloqueia mesmas condições com outputs diferentes', () => {
        const errors = validateConfig({
            version: 1,
            scenarios: [
                tributariaIrScenario('s1', 'IR 1,5%'),
                {
                    ...tributariaIrScenario('s2', 'IR 3%'),
                    outputs: [
                        {
                            id: 'o1',
                            field: 'incideIR',
                            value: { ativo: true, aliquota: '3%' },
                        },
                    ],
                },
            ],
        });
        expect(errors.some((err) => err.includes('Condições duplicadas'))).toBe(true);
    });

    it('permite cenários com condições distintas e mesmo output', () => {
        const errors = validateConfig({
            version: 1,
            scenarios: [
                tributariaIrScenario('s1', 'Tributária'),
                {
                    ...tributariaIrScenario('s2', 'Federal'),
                    conditions: [{ id: 'c1', field: 'esfera', operator: 'eq', value: 'Federal' }],
                },
            ],
        });
        expect(errors.some((err) => err.includes('duplicad'))).toBe(false);
        expect(errors.some((err) => err.includes('Conflito potencial'))).toBe(false);
    });

    it('não bloqueia save por conflito potencial de outputs (só painel/aviso)', () => {
        const errors = validateConfig({
            version: 1,
            scenarios: [
                tributariaIrScenario('s1', 'Tributária'),
                {
                    id: 's2',
                    name: 'Federal',
                    logic: 'AND',
                    conditions: [{ id: 'c1', field: 'esfera', operator: 'eq', value: 'Federal' }],
                    outputs: [
                        {
                            id: 'o1',
                            field: 'incideIR',
                            value: { ativo: true, aliquota: '3%' },
                        },
                    ],
                },
            ],
        });
        expect(errors.some((err) => err.includes('Conflito potencial'))).toBe(false);
        expect(
            detectPotentialOutputConflicts([
                tributariaIrScenario('s1', 'Tributária'),
                {
                    id: 's2',
                    name: 'Federal',
                    logic: 'AND',
                    conditions: [{ id: 'c1', field: 'esfera', operator: 'eq', value: 'Federal' }],
                    outputs: [
                        {
                            id: 'o1',
                            field: 'incideIR',
                            value: { ativo: true, aliquota: '3%' },
                        },
                    ],
                },
            ]).length,
        ).toBeGreaterThan(0);
    });

    it('permite outputs diferentes quando SE é disjunto', () => {
        const errors = validateConfig({
            version: 1,
            scenarios: [
                {
                    id: 's1',
                    name: 'Estadual',
                    logic: 'AND',
                    conditions: [{ id: 'c1', field: 'esfera', operator: 'eq', value: 'Estadual' }],
                    outputs: [
                        {
                            id: 'o1',
                            field: 'incideIR',
                            value: { ativo: true, aliquota: '1,5%' },
                        },
                    ],
                },
                {
                    id: 's2',
                    name: 'Federal',
                    logic: 'AND',
                    conditions: [{ id: 'c1', field: 'esfera', operator: 'eq', value: 'Federal' }],
                    outputs: [
                        {
                            id: 'o1',
                            field: 'incideIR',
                            value: { ativo: true, aliquota: '3%' },
                        },
                    ],
                },
            ],
        });
        expect(errors.some((err) => err.includes('Conflito potencial'))).toBe(false);
    });
});

describe('canManageCalculatorTriggers', () => {
    it('exige host celer, role MASTER e superuser', () => {
        expect(
            canManageCalculatorTriggers({
                host: 'celer',
                role: 'MASTER',
                isSuperuser: true,
            }),
        ).toBe(true);
        expect(
            canManageCalculatorTriggers({
                host: 'nw',
                role: 'MASTER',
                isSuperuser: true,
            }),
        ).toBe(false);
    });
});

