'use client';

import { useAutoAnimate } from '@formkit/auto-animate/react';
import { Copy, GitBranch, Loader2, Plus, Save, Trash2, Workflow } from 'lucide-react';

import {
    CALC_SECTION_LABEL_CLASS,
    CALC_SEGMENTED_LIST_COMPACT_CLASS,
    CALC_SEGMENTED_TRIGGER_COMPACT_CLASS,
} from '@/components/calculadora/calculadora-panel-classes';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import { Input } from '@/components/ui/input';
import { Switch } from '@/components/ui/switch';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { COLORS, ProductSelect, ProductMultiSelect, TYPOGRAPHY } from '@/design-system';
import { getTribunalComboboxOptions } from '@/functions/calcform/tribunal-combobox-options';
import {
    conditionValueToArray,
    isMultiselectConditionField,
} from '@/functions/calculator-triggers/condition-value';
import {
    ALIQUOTAS_IR,
    BASES_RRA,
    CONDITION_FIELDS,
    newCondition,
    newOutput,
    normalizeScenarioIrForTributaria,
    OPERATORS,
    outputInitialValue,
