    productDialogOutlineButtonClass,
    productDialogPrimaryButtonClass,
} from '@/design-system';
import { newScenario, validateScenario } from '@/functions/calculator-triggers/schema';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import type { TriggerScenario } from '@/types/calculator-triggers';

import { TriggerScenarioEditor } from './TriggerScenarioEditor';

interface TriggerCreateScenarioDialogProps {
    open: boolean;
    nextIndex: number;
    onOpenChange: (open: boolean) => void;
    onConfirm: (scenario: TriggerScenario) => void;
}

export function TriggerCreateScenarioDialog({
    open,
    nextIndex,
    onOpenChange,
    onConfirm,
}: TriggerCreateScenarioDialogProps) {
    const [draft, setDraft] = useState<TriggerScenario>(() => newScenario(nextIndex));

    useEffect(() => {
        if (!open) return;
        setDraft(newScenario(nextIndex));
    }, [open, nextIndex]);

    function handleConfirm() {
        const errors = validateScenario(draft);
        if (errors.length) {
            sendToastMessage({
                type: 'error',
                title: 'Validação falhou',
                description: errors.slice(0, 3).join(' '),

